package com.pp.shaderlod.measurement;
import java.nio.file.*;import java.nio.file.attribute.BasicFileAttributes;import java.io.*;import java.security.*;import java.util.*;import java.util.function.Supplier;import java.util.zip.ZipFile;
/** Exact loader origins only. Capture at phase boundaries; never scan CodeSource/native filesystem root. */
public final class ModArtifactIdentity {
 public record Origins(String loader,String scope,List<Path> inputs,List<Path> roots,boolean completePhysicalInputs){public Origins(String loader,String scope,List<Path> inputs,List<Path> roots){this(loader,scope,inputs,roots,true);}public Origins{inputs=List.copyOf(inputs);roots=List.copyOf(roots);}}
 private static Supplier<Origins> supplier;private static final int MAX_FILES=50000;private static final long MAX_BYTES=512L*1024*1024;
 private ModArtifactIdentity(){}
 public static void configure(Supplier<Origins> origin){supplier=Objects.requireNonNull(origin);}
 public static Map<String,String> capture(Class<?>... anchors){var origin=supplier;if(origin==null)return invalid("loader supplier unavailable");try{var initial=origin.get();var result=stableCapture(initial,anchors,()->{if(origin!=supplier)throw new IllegalStateException("Unstable loader origin supplier");var next=origin.get();if(!Objects.equals(initial,next))throw new IllegalStateException("Unstable loader origins");});if(origin!=supplier)return invalid("Unstable loader origin supplier after revalidation");return result;}catch(Exception|LinkageError e){return invalid(e.getClass().getSimpleName()+": "+e.getMessage());}}
 private static Map<String,String> invalid(String why){return Map.of("mod_artifact_valid","false","mod_artifact_scope","unavailable; no inferred artifact","mod_artifact_error",why);}
 public static Map<String,String> capture(Origins o,Class<?>... anchors){return stableCapture(o,anchors,()->{});}
 private static Map<String,String> stableCapture(Origins o,Class<?>[] anchors,Runnable checkOrigin){try{
  if(anchors.length==0)return invalid("Backend anchor required");var first=captureOnce(o,anchors);if(!"true".equals(first.get("mod_artifact_valid")))return first;
  // Read the loader origins again after anchor consumers, then reopen/re-enumerate every byte.
  // Sample origins after that pass too; final byte pass covers writes performed by that sample.
  for(int pass=0;pass<2;pass++){checkOrigin.run();var next=captureOnce(o);if(!"true".equals(next.get("mod_artifact_valid")))return invalid("Unstable artifact: "+next.get("mod_artifact_error"));var comparable=new TreeMap<>(next);comparable.put("mod_artifact_backend_anchors",first.get("mod_artifact_backend_anchors"));if(!first.equals(comparable))return invalid("Unstable artifact roots/module/archive identity during capture");}
  var stable=new TreeMap<>(first);stable.put("mod_artifact_stability","three complete bounded byte/manifest passes; origin samples before each revalidation; no atomic filesystem snapshot claim");return Map.copyOf(stable);
 }catch(Exception|LinkageError e){return invalid("Unstable artifact/origin: "+e.getClass().getSimpleName()+": "+e.getMessage());}}
 private static Map<String,String> captureOnce(Origins o,Class<?>... anchors){var opened=new ArrayList<java.nio.file.FileSystem>();try{
  if(o==null||o.inputs().isEmpty()||o.roots().isEmpty()||o.inputs().size()>16||o.roots().size()>16)throw new IOException("Missing/broad loader origin roots");
  var inputs=new ArrayList<Path>();var roots=new ArrayList<Path>();var seen=new HashSet<String>();for(Path p:o.inputs()){validate(p);String id=p.toUri().toString();if(!seen.add(id))throw new IOException("Duplicate loader input");inputs.add(p);}
  seen.clear();for(Path p:o.roots()){validate(p);if(!seen.add(p.toUri().toString()))throw new IOException("Duplicate module root");if(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)){var fs=FileSystems.newFileSystem(p,Map.of());opened.add(fs);p=fs.getPath("/");}if(!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("Invalid module root");roots.add(p);}
  boolean archive=inputs.size()==1&&Files.isRegularFile(inputs.getFirst(),LinkOption.NOFOLLOW_LINKS);var inputHashes=new TreeMap<String,String>();long[] inputBytes={0};
  for(Path p:inputs)if(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)){try(var z=new ZipFile(p.toFile())){var names=new HashSet<String>();for(var e:z.stream().toList())if(!names.add(e.getName()))throw new IOException("Duplicate archive member");}inputHashes.put(p.toUri().toString(),hash(p,inputBytes));}else if(!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("Invalid loader input");
  var entries=new TreeMap<String,String>();long[] bytes={0};int[] count={0},nodes={0};var locations=new TreeMap<String,Path>();
  for(int index=0;index<roots.size();index++){Path root=roots.get(index);int i=index;Files.walkFileTree(root,new SimpleFileVisitor<>(){
   public FileVisitResult preVisitDirectory(Path p,BasicFileAttributes a)throws IOException{if(Files.isSymbolicLink(p)||++nodes[0]>MAX_FILES||root.relativize(p).getNameCount()>64)throw new IOException("Symbolic link/broad module directory");return FileVisitResult.CONTINUE;}
   public FileVisitResult visitFile(Path p,BasicFileAttributes a)throws IOException{if(!a.isRegularFile()||Files.isSymbolicLink(p)||++count[0]>MAX_FILES)throw new IOException("Invalid/broad module manifest");String name=root.relativize(p).toString().replace('\\','/');if(locations.putIfAbsent(name,p)!=null)throw new IOException("Duplicate module member: "+name);entries.put(i+":"+name,hash(p,bytes));return FileVisitResult.CONTINUE;}
  });}
  if(entries.isEmpty())throw new IOException("Empty module view");var pins=new TreeMap<String,String>();var anchorMap=new TreeMap<String,String>();
  for(Class<?> a:anchors){String name=a.getName().replace('.','/')+".class";Path member=locations.get(name);if(member==null)throw new IOException("Backend anchor absent from loader module: "+name);byte[] actual;try(var in=a.getResourceAsStream("/"+name)){if(in==null)throw new IOException("Backend anchor resource unavailable");actual=in.readAllBytes();}String digest=sha(actual);String manifest=entries.entrySet().stream().filter(e->e.getKey().endsWith(":"+name)).findFirst().orElseThrow().getValue();if(!digest.equals(manifest))throw new IOException("Backend anchor differs from loader module");var code=a.getProtectionDomain().getCodeSource();if(code==null)throw new IOException("Backend code origin unavailable");var uri=code.getLocation().toURI();if("file".equals(uri.getScheme())){Path origin=Path.of(uri).toAbsolutePath().normalize();if(inputs.stream().noneMatch(x->x.getFileSystem().equals(FileSystems.getDefault())&&x.equals(origin)))throw new IOException("Backend file code origin is outside declared loader inputs");}anchorMap.put(name,digest+" @ "+(code==null?"unavailable":code.getLocation().toExternalForm()));}
  pins.put("mod_artifact_valid","true");pins.put("mod_artifact_complete_physical_inputs",Boolean.toString(o.completePhysicalInputs()));pins.put("mod_artifact_kind",archive?"loaded archive":inputs.stream().allMatch(x->x.getFileSystem().equals(FileSystems.getDefault())&&Files.isDirectory(x))?"exploded loader module manifest":"loader module view manifest");pins.put("mod_artifact",inputs.stream().map(p->p.toUri().toString()).toList().toString());pins.put("mod_artifact_roots",roots.stream().map(p->p.toUri().toString()).toList().toString());pins.put("mod_artifact_loader",o.loader());pins.put("mod_artifact_scope",o.scope()+"; full bounded module-view bytes; source anchor resources, not transformed in-memory classes");pins.put("mod_artifact_manifest",entries.toString());pins.put("mod_artifact_manifest_sha256",manifestHash(entries));pins.put("mod_artifact_sha256",archive?inputHashes.values().iterator().next():pins.get("mod_artifact_manifest_sha256"));pins.put("mod_artifact_input_archives",inputHashes.toString());pins.put("mod_artifact_backend_anchors",anchorMap.toString());pins.put("mod_artifact_files",Integer.toString(count[0]));pins.put("mod_artifact_bytes",Long.toString(bytes[0]));return Map.copyOf(pins);
 }catch(Exception|LinkageError e){return invalid(e.getClass().getSimpleName()+": "+e.getMessage());}finally{for(var fs:opened)try{fs.close();}catch(IOException ignored){}}}
 private static void validate(Path p)throws IOException{if(p==null||!p.isAbsolute()||!p.equals(p.normalize())||Files.isSymbolicLink(p)||!Files.exists(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("Invalid loader path");if(p.getFileSystem().equals(FileSystems.getDefault())){Path home=Path.of(System.getProperty("user.home")).toAbsolutePath().normalize();if(p.getParent()==null||home.startsWith(p))throw new IOException("Refused filesystem root/home ancestor");for(Path n=p;n!=null;n=n.getParent())if(Files.isSymbolicLink(n))throw new IOException("Symlink loader path ancestry");}}
 private static String hash(Path p,long[] total)throws IOException{try(var in=Files.newInputStream(p)){var d=MessageDigest.getInstance("SHA-256");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){total[0]+=n;if(total[0]>MAX_BYTES)throw new IOException("Artifact byte bound exceeded");d.update(b,0,n);}return HexFormat.of().formatHex(d.digest());}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 private static String manifestHash(Map<String,String> entries){var canonical=new StringBuilder();entries.forEach((name,digest)->canonical.append(name).append((char)0).append(digest).append((char)10));return sha(canonical.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 private static String sha(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
}
